		'· demo 09' => '· Demo 09',
		'move me' => 'bewege mich',
		'Words' => 'Wörter',
		'Nearest word' => 'Nächstgelegenes Wort',
		'Move the pointer across the meadow.' => 'Bewege den Zeiger über die Wiese.',
		'Dog' => 'Hund',
